INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-three-cols', 0, 'lab', 'Три равные колонки', 'Разметка задана и меняться не может. Сделайте контейнер .layout сеткой из трёх равных колонок (используйте единицу fr) с промежутком 12px между ячейками.', '', 'display: grid включает сетку; grid-template-columns: repeat(3, 1fr) задаёт три равные доли; gap — промежуток.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-fr-mix', 1, 'lab', 'Фиксированная и две резиновые', 'Контейнер .page — сетка из трёх колонок: первая ровно 200px, остальные делят оставшееся место: вторая получает одну долю, третья — две.', '', 'Размеры дорожек пишутся через пробел: 200px 1fr 2fr. Единица fr делит место, которое осталось после фиксированных колонок.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-gap', 2, 'lab', 'Промежутки по строкам и колонкам', 'Сетка .grid уже включена в разметке: три колонки и шесть ячеек. Задайте промежутки: 8px между строками и 24px между колонками.', '', 'Сокращение gap принимает два значения: сначала для строк, потом для колонок. Можно и по отдельности: row-gap и column-gap.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-rows', 3, 'lab', 'Строки сетки', 'Контейнер .box высотой 300px уже стал сеткой. Задайте три строки: шапка 60px, подвал 40px, а содержимое между ними занимает всё оставшееся место.', '', 'grid-template-rows работает так же, как grid-template-columns: 60px 1fr 40px.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-auto-fit', 4, 'lab', 'Адаптивная сетка без медиа-запросов', 'Сделайте из .cards адаптивную сетку: колонки шириной не меньше 200px, сколько поместится в строку, растянутые на всю ширину (repeat с auto-fit и minmax). Промежуток — 16px. Медиа-запросы не нужны.', '', 'grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); не забудьте display: grid и gap: 16px. Измените ширину предпросмотра и посмотрите, как меняется число колонок.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-span', 5, 'lab', 'Элемент на две колонки', 'В сетке .grid четыре колонки. Сделайте так, чтобы элемент .wide занимал две колонки (используйте grid-column).', '', 'grid-column: span 2 — «займи две дорожки от своего места». Можно и по линиям: 1 / 3.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-full-row', 6, 'lab', 'Заголовок на всю строку', 'В сетке .grid три колонки, но их число может измениться. Растяните заголовок .title на всю строку — от первой линии до последней, чтобы это работало при любом числе колонок.', '', 'Отрицательные номера линий считаются с конца: grid-column: 1 / -1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-areas', 7, 'lab', 'Страница по областям', 'Раскройте раскладку .page с помощью именованных областей: слева колонка меню шириной 200px, справа резиновое содержимое; шапка и подвал занимают обе колонки. Названия областей — header, nav, main и footer, у каждого элемента должен быть свой grid-area.', '', 'На .page: display: grid; grid-template-columns: 200px 1fr; grid-template-areas: "header header" "nav main" "footer footer". На элементах: header { grid-area: header } и так далее.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-center', 8, 'lab', 'Содержимое в центре ячеек', 'Сетка .grid уже построена: три колонки, у ячеек высота 80px. Расположите содержимое каждой ячейки в её центре — и по горизонтали, и по вертикали, одним сокращением.', '', 'place-items: center — сокращение для align-items и justify-items сразу.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-content', 9, 'lab', 'Сетка внутри контейнера', 'Контейнер .box высотой 240px — сетка из двух колонок по 80px, места остаётся много. Прижмите колонки к левому и правому краям, разделив свободное место между ними (space-between), а по вертикали поместите сетку в центр контейнера.', '', 'justify-content выравнивает дорожки по горизонтали, align-content — по вертикали. Сокращение place-content принимает их в порядке «align justify».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-auto-rows', 10, 'lab', 'Высота неявных строк', 'В сетке .grid три колонки, а элементов семь — браузер сам достроит строки. Сделайте высоту каждой такой строки ровно 100px.', '', 'За размер неявных строк отвечает grid-auto-rows.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-auto-rows-minmax', 11, 'lab', 'Строки не ниже, но растут', 'Неявные строки сетки .grid должны быть не ниже 80px, но вырастать, если текст в ячейке длиннее.', '', 'grid-auto-rows: minmax(80px, auto) — минимум 80px, максимум по содержимому.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-dense', 12, 'lab', 'Плотная упаковка', 'В галерее .gallery есть широкие плитки (.wide), из-за них в сетке остаются дыры. Включите плотную упаковку, чтобы последующие плитки занимали пустые места, сохранив построчное заполнение.', '', 'grid-auto-flow: row dense (достаточно и одного слова dense).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-sidebar', 13, 'lab', 'Боковая панель и содержимое', 'Контейнер .layout должен быть сеткой из двух колонок: боковая панель фиксированной ширины 240px и резиновое содержимое, которое занимает всё остальное место. Между колонками — промежуток 24px.', '', 'grid-template-columns: 240px 1fr; gap: 24px.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-narrow', 14, 'lab', 'Одна колонка на узком окне', 'Сделайте .cards сеткой из трёх равных колонок с промежутком 16px, а на экранах не шире 600px — одной колонкой. Используйте @media (max-width: …).', '', 'Сначала обычные правила для широкого экрана: display: grid и repeat(3, 1fr). Потом @media (max-width: 600px) { .cards { grid-template-columns: 1fr; } }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-nested', 15, 'lab', 'Сетка внутри ячейки', 'Внешний контейнер .outer — сетка из двух равных колонок с промежутком 16px. Внутри каждой карточки блок .inner — своя сетка тоже из двух равных колонок с промежутком 8px.', '', 'Вложенная сетка — обычный контейнер: .inner { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-subgrid', 16, 'lab', 'Карточки на общих строках', 'Внешняя сетка .cards уже построена: три колонки и три строки. Сделайте каждую карточку .card сеткой, которая занимает три строки родителя и берёт их себе (subgrid), чтобы заголовки, тексты и ссылки лежали на общих линиях.', '', 'Карточке нужны display: grid, grid-row: span 3 и grid-template-rows: subgrid.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-page-lines', 17, 'lab', 'Страница по линиям', 'Соберите каркас .page без областей, только по линиям: две колонки (меню 200px и резиновое содержимое) и три строки (шапка по содержимому, основа занимает всё остальное, подвал по содержимому), высота — не меньше высоты окна (100vh). Шапка и подвал растянуты на обе колонки.', '', 'На .page: display: grid; grid-template-columns: 200px 1fr; grid-template-rows: auto 1fr auto; min-height: 100vh. Шапке и подвалу: grid-column: 1 / -1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-auto-fill', 18, 'lab', 'Пустые дорожки остаются', 'В галерее .gallery всего три плитки, но колонки должны остаться на своих местах и не растягиваться на всю ширину: колонки не уже 120px, их столько, сколько поместится, пустые дорожки не схлопываются (auto-fill). Промежуток — 8px.', '', 'repeat(auto-fill, minmax(120px, 1fr)): в отличие от auto-fit, пустые дорожки сохраняются.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 20, 'w20-row-span', 19, 'lab', 'Высокая плитка', 'В галерее .gallery три колонки. Сделайте плитку .tall высотой в две строки сетки (grid-row).', '', 'grid-row: span 2 — по аналогии с grid-column: span 2.', '{}');
